use std::io;
use tokio::fs;
use tokio::io::AsyncReadExt;
use std::fs::File;

pub async fn discover_project_doc_paths(config: &Config) -> io::Result<Vec<PathBuf>> {
    let mut project_doc_paths = Vec::new();

    if config.project_doc_max_bytes == 0 {
        return Ok(project_doc_paths);
    }

    let candidate_filenames = candidate_filenames(config);
    let mut current_dir = config.cwd.clone();

    while let Some(parent) = current_dir.parent() {
        for filename in candidate_filenames.iter() {
            let path = current_dir.join(filename);
            if let Ok(metadata) = fs::metadata(&path).await {
                if metadata.is_file() && metadata.len() as usize <= config.project_doc_max_bytes {
                    project_doc_paths.push(path);
                }
            }
        }
        current_dir = parent.to_path_buf();
    }

    Ok(project_doc_paths)
}
