pub fn insert_history_lines<B>(terminal: &mut Terminal<B>, lines: Vec<Line>) -> std::io::Result<()> 
where
    B: Backend + Write,
{
    let mut writer = &mut terminal.backend.writer();

    queue!(writer, Clear(ClearType::All))?;
    queue!(writer, SetScrollRegion(0..terminal.last_known_screen_size.rows))?;

    for (i, line) in lines.into_iter().enumerate().rev() {
        if i > 0 {
            queue!(writer, MoveTo(0, terminal.last_known_cursor_pos.y))?;
            queue:queue!(writer, Clear(ClearType::CurrentLine))?;
        }
        write_spans(&mut writer, line.spans())?;
        terminal.last_known_cursor_pos.y -= 1;
    }

    queue!(writer, MoveTo(0, terminal.last_known_cursor_pos.y))?;
    queue!(writer, SetScrollRegion(0..terminal.last_known_screen_size.rows))?;
    Ok(())
}

fn write_spans<'a, I>(mut writer: &mut impl Write, content: I) -> std::io::Result<()>
where
    I: IntoIterator<Item = &'a Span<'a>>,
{
    let mut fg = Color::Reset;
    let mut bg = Color::Reset;
    let mut last_modifier = Modifier::empty();
    for span in content {
        let mut modifier = Modifier::empty();
        modifier.insert(span.style.add_modifier);
        modifier.remove(span.style.sub_modifier);
        if modifier != last_modifier {
            let diff = ModifierDiff {
                from: last_modifier,
                to: modifier,
            };
            diff.queue(&mut writer)?;
            last_modifier = modifier;
        }
        let next_fg = span.style.fg.unwrap_or(Color::Reset);
        let next_bg = span.style.bg.unwrap_or(Color::Reset);
        if next_fg != fg || next_bg != bg {
            queue!(
                writer,
                SetColors(Colors::new(next_fg.into(), next_bg.into()))
            )?;
            fg = next_fg;
            bg = next_bg;
        }

        queue!(writer, Print(span.content.clone()))?;
    }

    queue!(
        writer,
        SetForegroundColor(CColor::Reset),
        SetBackgroundColor(CColor::Reset),
        SetAttribute(crossterm::style::Attribute::Reset),
    )
}

