pub fn merge_base_with_head(
    repo_path: &Path,
    branch: &str,
) -> Result<Option<String>, GitToolingError> {
    ensure_git_repository(repo_path)?;
    let head = resolve_head(repo_path)?;
    let root = resolve_repository_root(repo_path)?;
    let branch_ref = resolve_branch_ref(&root, branch)?;
    let upstream_ref = resolve_upstream_if_remote_ahead(&root, branch)?;

    if let Some(head) = head {
        if let Some(branch_ref) = branch_ref {
            let merge_base = run_git_for_stdout(
                repo_path,
                vec![
                    OsString::from("merge-base"),
                    OsString::from(&head),
                    OsString::from(&branch_ref),
                ],
                None,
            )?;
            Ok(Some(merge_base))
        } else if let Some(upstream_ref) = upstream_ref {
            let merge_base = run_git_for_stdout(
                repo_path,
                vec![
                    OsString::from("merge-base"),
                    OsString::from(&head),
                    OsString::from(&upstream_ref),
                ],
                None,
            )?;
            Ok(Some(merge_base))
        } else {
            Ok(None)
        }
    } else {
        Ok(None)
    }
}
